const eventPool=[
 {type:'Economy',icon:'↗',title:'A fragile recovery takes hold',text:'New factory orders are up, but business leaders warn that power costs could choke the momentum. Your cabinet wants a clear signal.',choices:[['Accelerate clean energy','Invest in grid capacity and offer a targeted credit.','Growth +0.3 • Treasury −2.0 • Approval +2',s=>{s.treasury-=2;s.growth+=.3;s.approval+=2;s.infrastructure+=1}],['Let markets lead','Hold spending and allow private investment to respond.','Treasury +0.8 • Growth +0.1 • Approval −1',s=>{s.treasury+=.8;s.growth+=.1;s.approval-=1}],['Cut power levies','Reduce costs now, accepting a revenue hit.','Approval +3 • Treasury −1.2 • Inflation −0.2',s=>{s.approval+=3;s.treasury-=1.2;s.inflation-=.2}]]},
 {type:'Cabinet',icon:'◈',title:'A minister faces scrutiny',text:'Documents suggest the infrastructure minister awarded a contract to a former business associate. The opposition is demanding an inquiry.',choices:[['Order an independent inquiry','Protect due process and publish the findings.','Trust +4 • Stability +2 • Growth −0.1',s=>{s.approval+=2;s.stability+=2;s.corruption-=3;s.growth-=.1}],['Dismiss the minister today','Signal zero tolerance, but unsettle the coalition.','Approval +3 • Coalition −3 • Stability +1',s=>{s.approval+=3;s.coalition-=3;s.stability+=1;s.corruption-=2;s.ministers[4].name='Acting Minister'}],['Defend the minister','Keep projects moving; risk looking compromised.','Growth +0.2 • Approval −4 • Corruption +3',s=>{s.growth+=.2;s.approval-=4;s.corruption+=3}]]},
 {type:'Diplomacy',icon:'◎',title:'A regional trade offer',text:'Serevan has proposed a tariff-light corridor for medical equipment and advanced components. Domestic manufacturers seek safeguards.',choices:[['Sign a balanced trade pact','Open the corridor with a three-year review clause.','Trade + • Growth +0.2 • Relation +8',s=>{s.countries.find(c=>c.id==='serevan').relation+=8;s.countries.find(c=>c.id==='serevan').trade+=5;s.growth+=.2;s.treasury-=.4}],['Seek stronger safeguards','Request local-content rules before signing.','Relation +2 • Approval +1 • Deal delayed',s=>{s.countries.find(c=>c.id==='serevan').relation+=2;s.approval+=1}],['Decline for now','Protect local industry and preserve policy room.','Approval +1 • Relation −4 • Growth −0.1',s=>{s.approval+=1;s.countries.find(c=>c.id==='serevan').relation-=4;s.growth-=.1}]]},
 {type:'Security',icon:'⌖',title:'Unidentified aircraft near the coast',text:'Radar tracked two aircraft near the northern maritime boundary. They withdrew before interception. Intelligence cannot yet confirm their origin.',choices:[['Open a military hotline','Request clarification through the regional security channel.','Stability +3 • Relation with Orvaska +5',s=>{s.stability+=3;s.countries.find(c=>c.id==='orvaska').relation+=5;s.readiness-=1}],['Scramble patrol aircraft','Show readiness and increase surveillance.','Readiness +4 • Treasury −1.5 • Tension +',s=>{s.readiness+=4;s.treasury-=1.5;s.countries.find(c=>c.id==='orvaska').relation-=4;s.stability-=1}],['Issue a public warning','Put the incident on the record without escalation.','Approval +2 • Stability −1',s=>{s.approval+=2;s.stability-=1}]]},
 {type:'Society',icon:'✳',title:'Severe storms threaten the east',text:'Emergency services expect flooding in two provinces. Local leaders are asking for rapid assistance and temporary shelters.',choices:[['Deploy emergency funds','Send relief teams and open shelters now.','Approval +4 • Treasury −2.5 • Stability +2',s=>{s.approval+=4;s.treasury-=2.5;s.stability+=2;s.health+=1}],['Ask provinces to lead','Coordinate national logistics, leaving spending local.','Treasury −0.8 • Approval +1',s=>{s.treasury-=.8;s.approval+=1}],['Wait for confirmed damage','Preserve reserves until the scale is clear.','Treasury +0.5 • Approval −5 • Stability −3',s=>{s.treasury+=.5;s.approval-=5;s.stability-=3}]]},
 {type:'Politics',icon:'▤',title:'Opposition demands a confidence vote',text:'Three coalition lawmakers are threatening to withhold support unless you present a costed jobs plan before the next session.',choices:[['Table a jobs compact','Bring employers and unions into a funded package.','Coalition +5 • Approval +2 • Treasury −1.2',s=>{s.coalition+=5;s.approval+=2;s.treasury-=1.2;s.unemployment-=.3}],['Call their bluff','Force the coalition to choose between unity and an election.','Coalition −5 • Approval +1 • Stability −2',s=>{s.coalition-=5;s.approval+=1;s.stability-=2}],['Offer committee concessions','Give partners a formal role in shaping the plan.','Coalition +3 • Corruption +1',s=>{s.coalition+=3;s.corruption+=1}]]},
 {type:'Health',icon:'✚',title:'Hospitals report staffing pressure',text:'Nurses in the national hospital network say vacancies are affecting emergency wait times. A union ballot is planned next week.',choices:[['Fund a retention package','Raise night-shift pay and expand training placements.','Approval +3 • Treasury −1.8 • Health +2',s=>{s.approval+=3;s.treasury-=1.8;s.health+=2;s.unemployment-=.1}],['Negotiate phased changes','Set up talks with a near-term review.','Stability +2 • Approval +1',s=>{s.stability+=2;s.approval+=1}],['Hold the spending line','Ask hospitals to reorganize existing budgets.','Treasury +0.4 • Approval −3',s=>{s.treasury+=.4;s.approval-=3;s.health-=1}]]}
];
const clamp=(v,min=0,max=100)=>Math.max(min,Math.min(max,v));
const num=(v,d=1)=>Number(v).toFixed(d);
const freshState=()=>({version:1,month:1,year:2028,day:1,treasury:42.6,debt:56.2,gdp:842,growth:.34,inflation:3.1,unemployment:7.8,approval:56,coalition:61,stability:72,corruption:24,readiness:63,loyalty:72,personnel:118,defence:18,army:62,air:54,navy:47,health:61,education:58,infrastructure:53,tax:24,budget:{health:5,education:4,infrastructure:4,defence:5,welfare:4,admin:2},ministers:baseMinisters.map(x=>({role:x[0],name:x[1],bio:x[2]})),countries:worldSeed.map(c=>({...c})),projects:[],history:[],news:[],activeEvent:null,chart:[],unlocked:['overview'],flags:{},intel:64,threat:31,policy:'Balanced growth',gameOver:null,speed:0});
function loadState(){try{const p=JSON.parse(localStorage.getItem(SAVE_KEY));if(p&&p.version===1&&p.countries&&p.budget){const defaults=freshState().budget,budget={...defaults,...p.budget},total=Object.values(budget).reduce((a,b)=>a+Number(b||0),0);if(total>40){const scale=24/total;for(const key of Object.keys(budget))budget[key]=Math.round(Number(budget[key]||0)*scale*10)/10}const s={...freshState(),...p,speed:0,budget};if(typeof p.activeEvent==='string')s.activeEvent=eventPool.find(e=>e.title===p.activeEvent)||null;else if(p.activeEvent?.title)s.activeEvent=eventPool.find(e=>e.title===p.activeEvent.title)||null;return s}}catch(e){}return freshState()}
let state=loadState(),page='overview',activeModal=null,tickTimer=null,toastTimer=null;
const app=document.getElementById('app');
const navItems=[['overview','▦','Presidential overview'],['economy','◌','Economy & budget'],['government','♙','Government'],['military','⬡','Military command'],['diplomacy','◎','International relations'],['infrastructure','⌂','Infrastructure'],['intelligence','⌖','Intelligence'],['news','▤','News & events']];
const monthName=m=>new Date(2028,m-1,1).toLocaleString('en',{month:'long'});
const money=n=>`${n<0?'−':''}₡${Math.abs(n).toFixed(1)}B`;
function save(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));toast('Presidential archive saved')}catch(e){toast('Save unavailable in this browser')}}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function addNews(title,detail,type='Briefing'){state.news.unshift({title,detail,type,date:`${monthName(state.month)} ${state.year}`});state.news=state.news.slice(0,30)}
function stat(title,value,sub,icon,trend='',negative=false){return `<div class="card stat-card"><div class="stat-head"><span>${title}</span><span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${sub}${trend?` <span class="trend ${negative?'negative':''}">${trend}</span>`:''}</div></div>`}
function header(title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">Office of the President · ${monthName(state.month)} ${state.year}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function cardHead(title,sub='',right=''){return `<div class="card-head"><div><div class="card-title">${title}</div>${sub?`<div class="card-sub">${sub}</div>`:''}</div>${right}</div>`}
function chartSvg(){const vals=state.chart.length?state.chart:[state.gdp];const data=vals.slice(-12);while(data.length<8)data.unshift(data[0]||state.gdp);const min=Math.min(...data)-15,max=Math.max(...data)+15,pts=data.map((v,i)=>`${30+i*(540/(data.length-1))},${166-(v-min)/(max-min||1)*132}`).join(' ');const area=`30,168 ${pts} ${30+(data.length-1)*(540/(data.length-1))},168`;return `<svg viewBox="0 0 600 190" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#d9ad54" stop-opacity=".22"/><stop offset="1" stop-color="#d9ad54" stop-opacity="0"/></linearGradient></defs>${[34,76,118,160].map(y=>`<line x1="28" y1="${y}" x2="575" y2="${y}" class="chart-grid"/>`).join('')}<polygon points="${area}" fill="url(#area)"/><polyline points="${pts}" fill="none" stroke="#e1b658" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${data.map((v,i)=>`<circle cx="${30+i*(540/(data.length-1))}" cy="${166-(v-min)/(max-min||1)*132}" r="2.4" fill="#f2d28a"/>`).join('')}<text x="30" y="184" class="chart-label">12 MONTHS AGO</text><text x="516" y="184" class="chart-label">CURRENT</text><text x="33" y="24" class="chart-label">₡${Math.round(max)}B</text><text x="33" y="155" class="chart-label">₡${Math.round(min)}B</text></svg>`}
function dashboard(){const alerts=state.stability<45||state.coalition<40||state.treasury<10;return `${header('Presidential overview','A nation at a crossroads. Your decisions shape Veloria’s next chapter.',`<button class="btn gold" onclick="advance()">Advance month&nbsp; →</button>`)}<div class="grid stats-grid">${stat('NATIONAL GDP',`₡${state.gdp.toFixed(0)}B`,`Growth ${state.growth>=0?'+':''}${num(state.growth)}% / month`,'◌',`${state.growth>=0?'↗':'↘'} ${num(Math.abs(state.growth))}%`,state.growth<0)}${stat('TREASURY',money(state.treasury),`Debt ₡${state.debt.toFixed(1)}B`,'◈',state.treasury<15?'Reserve low':'On plan',state.treasury<15)}${stat('PUBLIC APPROVAL',`${Math.round(state.approval)}%`,`Coalition support ${Math.round(state.coalition)}%`,'♙',state.approval>=50?'↗ mandate steady':'↘ public confidence',state.approval<50)}${stat('NATIONAL STABILITY',`${Math.round(state.stability)}%`,`Security alert ${state.threat<35?'LOW':'ELEVATED'}`,'⬡',state.stability>=55?'Resilient':'Needs attention',state.stability<50)}</div><div class="grid dashboard-grid"><div><div class="card chart-card">${cardHead('Economic performance','Gross domestic product · last 12 months',`<div class="chart-legend"><span><i class="legend-dot"></i>GDP</span><span><i class="legend-dot blue"></i>Forecast</span></div>`)}<div class="chart-wrap">${chartSvg()}</div></div><div class="grid lower-grid"><div class="card">${cardHead('Cabinet pulse','Public service performance')}<div class="panel-body">${[['Health',state.health],['Education',state.education],['Infrastructure',state.infrastructure],['Defence readiness',state.readiness]].map(([n,v])=>`<div class="bar-row"><span class="bar-label">${n}</span><div class="bar-track"><div class="bar-fill" style="width:${clamp(v)}%"></div></div><span class="bar-value">${Math.round(v)}</span></div>`).join('')}</div></div><div class="card">${cardHead('National indicators','Monthly snapshot')}<div class="panel-body"><div class="bar-row"><span class="bar-label">Inflation</span><div class="bar-track"><div class="bar-fill" style="width:${clamp(state.inflation*8)}%;background:${state.inflation>5?'var(--red)':'var(--blue)'}"></div></div><span class="bar-value">${num(state.inflation)}%</span></div><div class="bar-row"><span class="bar-label">Unemployment</span><div class="bar-track"><div class="bar-fill" style="width:${clamp(state.unemployment*7)}%;background:#77a9ee"></div></div><span class="bar-value">${num(state.unemployment)}%</span></div><div class="bar-row"><span class="bar-label">Corruption</span><div class="bar-track"><div class="bar-fill" style="width:${clamp(state.corruption)}%;background:${state.corruption>45?'var(--red)':'var(--gold)'}"></div></div><span class="bar-value">${Math.round(state.corruption)}</span></div><div class="hint">Indicators update as policy takes effect.</div></div></div><div class="card">${cardHead('Cabinet brief','Latest from your ministers')}<div class="panel-body">${(state.news.slice(0,2).length?state.news.slice(0,2):[{title:'The morning brief is ready',detail:'Review national indicators and set the priorities for your first month.',type:'Briefing'}]).map(n=>`<div class="news-item"><div class="news-icon">◈</div><div class="news-copy"><strong>${n.title}</strong><small>${n.type} · ${n.date||'Today'}</small></div></div>`).join('')}</div></div></div></div><div class="grid" style="grid-template-columns:1.55fr 1fr;margin-top:14px"><div class="card">${cardHead('International outlook','Regional partners and strategic competitors',`<button class="btn small ghost" onclick="navigate('diplomacy')">Open diplomacy →</button>`)}<div class="panel-body" style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px">${state.countries.slice(0,3).map(c=>`<div class="mini-metric"><label>${c.flag} ${c.name}</label><strong>${c.relation>60?'Warm':c.relation>35?'Stable':'Tense'}</strong><small>Trade ₡${c.trade}B · ${c.stance}</small></div>`).join('')}</div></div><div class="card event-card"><div class="event-kicker"><span>◉ Presidential decision</span><span class="tag gold">${state.activeEvent?state.activeEvent.type:'Next briefing'}</span></div><h3>${state.activeEvent?state.activeEvent.title:'Your next decision is waiting'}</h3><p>${state.activeEvent?state.activeEvent.text:'Advance the calendar to see the next report from your ministers, intelligence service, or foreign office.'}</p><button class="btn gold" onclick="${state.activeEvent?'openEvent()':'advance()'}">${state.activeEvent?'Review report':'Advance to next month'} →</button></div></div>${alerts?`<div class="notice warn" style="margin-top:14px"><strong>⚠ Attention required.</strong> ${state.coalition<40?'Coalition support is fragile. ':' '}${state.stability<45?'National stability is under strain. ':' '}${state.treasury<10?'Treasury reserves are low.':''}</div>`:''}`}
function economy(){const total=Object.values(state.budget).reduce((a,b)=>a+b,0);return `${header('Economy & budget','Set the nation’s fiscal direction and balance services, investment, and resilience.',`<button class="btn gold" onclick="advance()">Set budget & advance →</button>`)}<div class="grid stats-grid">${stat('GDP',`₡${state.gdp.toFixed(1)}B`,`Monthly growth ${num(state.growth)}%`,'◌')}${stat('INFLATION',`${num(state.inflation)}%`,`Target range 2–4%`,'↗',state.inflation>5?'Elevated':'Manageable',state.inflation>5)}${stat('UNEMPLOYMENT',`${num(state.unemployment)}%`,`Labor force participation 68%`,'♙')}${stat('PUBLIC DEBT',`₡${state.debt.toFixed(1)}B`,`Debt / GDP ${num(state.debt/state.gdp*100,0)}%`,'◈')}</div><div class="grid two-col"><div class="card">${cardHead('National accounts','Fiscal year 2028 · ₡ billions')}<div class="panel-body"><div class="metric-row"><div class="mini-metric"><label>Monthly revenue</label><strong>${(state.gdp*state.tax/100/12).toFixed(1)}B</strong><small>Tax rate ${state.tax}%</small></div><div class="mini-metric"><label>Monthly spending</label><strong>${(state.gdp*total/100/12).toFixed(1)}B</strong><small>${total}% of GDP allocated</small></div><div class="mini-metric"><label>Projected balance</label><strong style="color:${state.tax>=total?'var(--green)':'var(--red)'}">${state.tax>=total?'+':''}${(state.gdp*(state.tax-total)/1200).toFixed(1)}B</strong><small>Monthly estimate</small></div></div><div style="height:12px"></div><div class="chart-wrap">${chartSvg()}</div></div></div><div class="card">${cardHead('Budget priorities','Monthly share of GDP')}<div class="panel-body">${Object.entries(state.budget).map(([k,v])=>`<div class="control-row"><div class="control-top"><label>${k[0].toUpperCase()+k.slice(1)}</label><output id="out-${k}">${v}%</output></div><input type="range" min="0" max="30" value="${v}" oninput="setBudget('${k}',this.value)"><div class="hint">${budgetHint(k)}</div></div>`).join('')}<div class="notice ${total>state.tax?'warn':''}" style="margin-top:12px"><strong>Allocation: ${total}% of GDP.</strong> Tax revenue is ${state.tax}%. ${total>state.tax?'This budget adds to public debt.':'Surplus supports treasury reserves and debt reduction.'}</div><div class="control-row"><div class="control-top"><label>Average tax rate</label><output id="out-tax">${state.tax}%</output></div><input type="range" min="12" max="40" value="${state.tax}" oninput="setTax(this.value)"><div class="hint">Higher taxes improve revenue but can slow growth and public approval.</div></div></div></div></div><div class="grid two-col" style="margin-top:14px"><div class="card">${cardHead('Economic outlook','Interconnected indicators')}<div class="panel-body"><div class="notice">Infrastructure and education investment boost long-run growth. Defence, healthcare, and welfare strengthen security and stability. Persistent deficits raise debt and can crowd out future investment.</div><div class="pill-row"><span class="tag">GDP ₡${state.gdp.toFixed(0)}B</span><span class="tag">Exports ₡${(state.gdp*.21).toFixed(0)}B</span><span class="tag">Imports ₡${(state.gdp*.18).toFixed(0)}B</span><span class="tag">Treasury ${money(state.treasury)}</span></div></div></div><div class="card">${cardHead('Fiscal doctrine','A broad strategic direction')}<div class="panel-body"><select class="select" onchange="setPolicy(this.value)"><option ${state.policy==='Balanced growth'?'selected':''}>Balanced growth</option><option ${state.policy==='Austerity'?'selected':''}>Austerity</option><option ${state.policy==='Public investment'?'selected':''}>Public investment</option><option ${state.policy==='Industrial renewal'?'selected':''}>Industrial renewal</option></select><p class="hint">Doctrine introduces a persistent monthly nudge to economic outcomes. You can change it at any time.</p></div></div></div>`}
function budgetHint(k){return {health:'Care capacity improves public wellbeing and workforce resilience.',education:'Skills, innovation, and productivity improve over time.',infrastructure:'Roads, power, and ports lift trade and long-term growth.',defence:'Funds readiness, personnel, and procurement.',welfare:'Supports household demand and social stability.',admin:'Keeps public services and government operating.'}[k]}
function government(){return `${header('Government','Build a capable cabinet, manage the governing coalition, and protect the democratic mandate.',`<button class="btn gold" onclick="openPolicyModal()">Introduce legislation +</button>`)}<div class="grid stats-grid">${stat('COALITION SUPPORT',`${Math.round(state.coalition)}%`,'Parliamentary confidence','♙',state.coalition>50?'Working majority':'Fragile majority',state.coalition<45)}${stat('PUBLIC APPROVAL',`${Math.round(state.approval)}%`,'Next election in '+(48-(state.month-1)%48)+' months','◈')}${stat('NATIONAL STABILITY',`${Math.round(state.stability)}%`,'Civic trust and institutional resilience','⬡')}${stat('CORRUPTION INDEX',`${Math.round(state.corruption)}/100`,'Lower is better','⌖','↓ integrity priority',state.corruption>40)}</div><div class="grid two-col"><div class="card">${cardHead('Council of Ministers','Appoint, replace, or release a minister')}<div class="panel-body" style="padding-top:2px"><table class="table"><thead><tr><th>Minister</th><th>Portfolio</th><th>Confidence</th><th></th></tr></thead><tbody>${state.ministers.map((m,i)=>`<tr><td><div class="person"><span class="person-avatar">${m.name.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><div><strong>${m.name}</strong><small>${m.bio}</small></div></div></td><td>${m.role}</td><td><span class="tag ${state.coalition<45?'red':'green'}">${state.coalition>50?'Trusted':'Questioned'}</span></td><td><button class="btn small ghost" onclick="replaceMinister(${i})">Replace</button></td></tr>`).join('')}</tbody></table></div></div><div class="card">${cardHead('Parliament','National Assembly · 180 seats')}<div class="panel-body"><div style="display:flex;justify-content:space-between;font-size:10px"><span>Governing coalition</span><strong>${Math.round(180*state.coalition/100)} seats</strong></div><div class="progress" style="height:11px;margin:9px 0 15px"><span style="width:${state.coalition}%;background:linear-gradient(90deg,#c59b4f 0 72%,#7195bb 72% 100%)"></span></div><div class="bar-row"><span class="bar-label">Civic Alliance</span><div class="bar-track"><div class="bar-fill" style="width:${state.coalition*.67}%"></div></div><span class="bar-value">${Math.round(180*state.coalition/150)}%</span></div><div class="bar-row"><span class="bar-label">Reform Bloc</span><div class="bar-track"><div class="bar-fill" style="width:${state.coalition*.33}%;background:#75a7e7"></div></div><span class="bar-value">${Math.round(180*state.coalition/300)}</span></div><div class="bar-row"><span class="bar-label">Opposition</span><div class="bar-track"><div class="bar-fill" style="width:${100-state.coalition}%;background:#bd7774"></div></div><span class="bar-value">${180-Math.round(180*state.coalition/100)}</span></div><div class="notice ${state.coalition<40?'danger':''}" style="margin-top:16px">${state.coalition<40?'<strong>Confidence at risk.</strong> Key bills may fail and a confidence vote may be called.':'<strong>Working relationship intact.</strong> Coalition support determines your room to pass legislation.'}</div><div style="display:flex;gap:8px;margin-top:12px"><button class="btn small" onclick="coalitionAction('consult')">Hold coalition council</button><button class="btn small" onclick="coalitionAction('reform')">Anti-corruption charter</button></div></div></div></div><div class="grid two-col" style="margin-top:14px"><div class="card">${cardHead('Institutional health','Trust, transparency, and national cohesion')}<div class="panel-body"><div class="bar-row"><span class="bar-label">Public trust</span><div class="bar-track"><div class="bar-fill" style="width:${state.approval}%"></div></div><span class="bar-value">${Math.round(state.approval)}</span></div><div class="bar-row"><span class="bar-label">Civic stability</span><div class="bar-track"><div class="bar-fill" style="width:${state.stability}%;background:#77a9ee"></div></div><span class="bar-value">${Math.round(state.stability)}</span></div><div class="bar-row"><span class="bar-label">Integrity</span><div class="bar-track"><div class="bar-fill" style="width:${100-state.corruption}%;background:#57c7a0"></div></div><span class="bar-value">${Math.round(100-state.corruption)}</span></div></div></div><div class="card">${cardHead('Presidential priorities','Choose policies with lasting consequences')}<div class="panel-body"><div class="notice"><strong>Policy: ${state.policy}.</strong> Your fiscal doctrine sets the tone for public investment, business confidence, and the next election.</div><div class="pill-row"><span class="tag gold">Term ${Math.ceil(state.month/48)}</span><span class="tag">Month ${state.month}</span><span class="tag">Elections every 48 months</span></div><button class="btn small" style="margin-top:13px" onclick="navigate('news')">Review political briefings →</button></div></div></div>`}
function military(){return `${header('Military command','Manage national defence, readiness, procurement, and security posture.',`<button class="btn gold" onclick="openProcurement()">Procurement & recruitment +</button>`)}<div class="grid stats-grid">${stat('DEFENCE READINESS',`${Math.round(state.readiness)}%`,'Operational readiness','⬡')}${stat('ACTIVE PERSONNEL',`${state.personnel}k`,'Across all services','♙')}${stat('COMMAND LOYALTY',`${Math.round(state.loyalty)}%`,'Civilian oversight essential','◈',state.loyalty<45?'Watch closely':'Stable',state.loyalty<45)}${stat('DEFENCE SPENDING',`${state.budget.defence}%`,'Share of GDP','₡')}</div><div class="grid two-col"><div class="card">${cardHead('Armed forces','Capability by service')}<div class="panel-body">${[['Ground forces',state.army,'brigades'],['Air command',state.air,'squadrons'],['Naval fleet',state.navy,'vessels']].map(([n,v,l])=>`<div style="margin-bottom:20px"><div style="display:flex;justify-content:space-between;font-size:10px;margin-bottom:8px"><strong>${n}</strong><span class="muted">${l} · ${Math.round(v)} readiness</span></div><div class="progress" style="height:8px"><span style="width:${clamp(v)}%;background:${v<45?'var(--red)':'var(--gold)'}"></span></div></div>`).join('')}<div class="metric-row"><div class="mini-metric"><label>Active bases</label><strong>14</strong><small>5 air · 7 ground · 2 naval</small></div><div class="mini-metric"><label>Equipment index</label><strong>${Math.round((state.army+state.air+state.navy)/3)}</strong><small>Modernization standing</small></div><div class="mini-metric"><label>Annual recruitment</label><strong>${Math.round(state.personnel*.06)}k</strong><small>Projected intake</small></div></div></div></div><div class="card">${cardHead('Strategic posture','Defence policy and civilian oversight')}<div class="panel-body"><div class="notice ${state.loyalty<45?'danger':''}"><strong>${state.loyalty<45?'Command confidence is deteriorating.':'Civilian authority is respected.'}</strong> Maintain transparent oversight and adequate service funding to protect national stability.</div><div class="control-row"><div class="control-top"><label>Defence allocation</label><output id="out-defence">${state.budget.defence}% of GDP</output></div><input type="range" min="5" max="30" value="${state.budget.defence}" oninput="setBudget('defence',this.value)"><div class="hint">More funding improves readiness over time but competes with public services.</div></div><div class="control-row"><div class="control-top"><label>Force posture</label></div><select class="select" onchange="setPosture(this.value)"><option>Defensive readiness</option><option>Regional deterrence</option><option>Peacekeeping focus</option></select><div class="hint">Posture influences readiness, costs, and neighboring relations.</div></div><div style="display:flex;gap:8px;margin-top:12px"><button class="btn small" onclick="militaryAction('exercise')">Joint readiness exercise</button><button class="btn small" onclick="militaryAction('oversight')">Strengthen civilian oversight</button></div></div></div></div><div class="card" style="margin-top:14px">${cardHead('Procurement pipeline','Modernization projects and status')}<div class="panel-body">${state.projects.filter(p=>p.kind==='military').length?state.projects.filter(p=>p.kind==='military').map(projectCard).join(''):'<div class="notice">No defence acquisitions underway. Open procurement to invest in secure communications, air defence, or fleet renewal.</div>'}</div></div>`}
function diplomacy(){return `${header('International relations','Every relationship is an opportunity, a commitment, or a risk.',`<button class="btn gold" onclick="diplomaticAction('summit')">Convene regional summit +</button>`)}<div class="grid two-col"><div><div class="map-card"><div class="map-land land-a"></div><div class="map-land land-b"></div><div class="map-land land-c"></div><div class="map-center"></div><div class="map-country">VELORIA</div><span class="map-label" style="left:18%;top:33%">TAVORA</span><span class="map-label" style="left:70%;top:27%">ORVASKA</span><span class="map-label" style="left:64%;top:69%">SEREVAN</span><span class="map-label" style="left:33%;top:72%">KARSIN</span><span class="map-label" style="left:77%;top:51%">LUMERIA</span></div><div class="notice" style="margin-top:12px"><strong>Foreign office assessment.</strong> Regional trade is expanding, but border rhetoric from Karsin and Orvaska merits close monitoring.</div></div><div class="card">${cardHead('Diplomatic priorities','Active agreements and exposure')}<div class="panel-body"><div class="mini-metric"><label>Trade volume</label><strong>₡${state.countries.reduce((a,c)=>a+c.trade,0).toFixed(0)}B</strong><small>Across ${state.countries.length} bilateral partners</small></div><div class="control-row"><div class="control-top"><label>Foreign affairs approach</label></div><select class="select" onchange="setDiplomacy(this.value)"><option>Constructive engagement</option><option>Trade-first diplomacy</option><option>Regional security</option><option>Strategic neutrality</option></select><div class="hint">A sustained diplomatic approach shapes how partners react to your actions.</div></div><div class="control-row"><label class="section-title">Current agreements</label><div class="pill-row"><span class="tag green">Veloria–Lumeria maritime accord</span><span class="tag">Serevan research exchange</span></div></div></div></div></div><div class="grid three-col" style="margin-top:14px">${state.countries.map(c=>`<div class="card country-card"><div class="country-top"><span class="country-flag">${c.flag}</span><div><div class="country-name">${c.name}</div><div class="country-meta">${c.system} · ${c.stance}</div></div></div><div class="country-stats"><div><small>HEAD OF STATE</small><b>${c.leader}</b></div><div><small>ECONOMY</small><b>₡${c.gdp.toFixed(0)}B GDP</b></div><div><small>BILATERAL TIES</small><b>${Math.round(c.relation)}/100</b></div><div><small>TRADE</small><b>₡${c.trade.toFixed(0)}B / yr</b></div></div><div class="country-meta">Resources: ${c.resources.join(' · ')}<br>Strategic interest: ${c.interest}</div><div class="bar-track" style="margin:9px 0 11px"><div class="bar-fill" style="width:${clamp(c.relation)}%;background:${c.relation<30?'var(--red)':'var(--gold)'}"></div></div><div class="country-actions"><button class="btn small" onclick="countryAction('${c.id}','trade')">Trade deal</button><button class="btn small" onclick="countryAction('${c.id}','treaty')">Propose treaty</button><button class="btn small ghost" onclick="countryAction('${c.id}','sanction')">Sanction</button></div></div>`).join('')}</div>`}
function infrastructure(){const items=[['Highway renewal','roads','Connect rural producers to the central freight corridor.',4,4],['Grid modernization','power','Reduce outages and improve industrial capacity.',5,5],['Regional hospitals','hospital','Expand emergency and maternity care in three provinces.',4,4],['Technical schools','school','Train workers for manufacturing and clean technology.',3,5],['Deep-water port','port','Increase export capacity and maritime access.',6,6],['Industrial innovation park','factory','Attract advanced manufacturing and skilled jobs.',5,5]];return `${header('Infrastructure','Build productive capacity for the next generation.',`<button class="btn gold" onclick="openBuildModal()">Commission project +</button>`)}<div class="grid stats-grid">${stat('INFRASTRUCTURE INDEX',`${Math.round(state.infrastructure)}/100`,'National network health','⌂')}${stat('ACTIVE PROJECTS',`${state.projects.length}`,'Projects in delivery','◈')}${stat('CAPITAL BUDGET',`${state.budget.infrastructure}%`,'GDP allocation','₡')}${stat('TRADE CAPACITY',`₡${(state.gdp*.21).toFixed(0)}B`,'Annual export potential','↗')}</div><div class="grid two-col"><div class="card">${cardHead('National development plan','Commission a project · costs are paid up front')}<div class="panel-body">${items.map(([name,kind,desc,cost,duration])=>`<div class="project"><div class="project-line"><span class="project-name">${name}</span><span class="tag">${cost}B · ${duration} mo</span></div><div class="project-desc">${desc}</div><button class="btn small" onclick="buildProject('${kind}','${name}',${cost},${duration})" ${state.treasury<cost?'disabled':''}>Commission project</button></div>`).join('')}</div></div><div><div class="card">${cardHead('Projects in delivery','Construction progress')}<div class="panel-body">${state.projects.length?state.projects.map(projectCard).join(''):'<div class="notice">No major projects are currently active. Commission new infrastructure to unlock future growth.</div>'}</div></div><div class="card" style="margin-top:14px">${cardHead('Regional development','Build capacity and resilience')}<div class="panel-body"><div class="bar-row"><span class="bar-label">Transport</span><div class="bar-track"><div class="bar-fill" style="width:${state.infrastructure+5}%"></div></div><span class="bar-value">${Math.round(state.infrastructure+5)}</span></div><div class="bar-row"><span class="bar-label">Energy</span><div class="bar-track"><div class="bar-fill" style="width:${state.infrastructure-3}%;background:#77a9ee"></div></div><span class="bar-value">${Math.round(state.infrastructure-3)}</span></div><div class="bar-row"><span class="bar-label">Public services</span><div class="bar-track"><div class="bar-fill" style="width:${(state.health+state.education)/2}%;background:#57c7a0"></div></div><span class="bar-value">${Math.round((state.health+state.education)/2)}</span></div><p class="hint">Completed infrastructure improves GDP and makes the economy more resilient to shocks.</p></div></div></div></div>`}
function intelligence(){return `${header('Intelligence & security','Protect the republic through early warning, oversight, and public resilience.',`<button class="btn gold" onclick="intelAction('review')">Request intelligence review</button>`)}<div class="grid stats-grid">${stat('AGENCY CAPACITY',`${Math.round(state.intel)}%`,'Analytic and field capability','⌖')}${stat('THREAT LEVEL',`${Math.round(state.threat)}/100`,'Domestic and regional alert','⚑','Assessment updated',state.threat>55)}${stat('NATIONAL STABILITY',`${Math.round(state.stability)}%`,'Civic resilience','⬡')}${stat('CYBER READINESS',`${Math.round(clamp(state.intel-7))}%`,'Critical infrastructure protection','▤')}</div><div class="grid two-col"><div class="card">${cardHead('Director’s assessment','CONFIDENTIAL · circulated to the President')}<div class="panel-body"><div class="notice ${state.threat>55?'warn':''}"><strong>Regional picture.</strong> ${state.countries.find(c=>c.id==='karsin').relation<25?'Karsin’s security posture remains opaque. Signals analysts recommend a quiet diplomatic channel.':'No immediate military escalation is assessed as likely.'}</div><div class="news-item"><div class="news-icon">⌖</div><div class="news-copy"><strong>Critical infrastructure monitoring</strong><small>Cyber defence posture is ${state.intel>70?'robust':'adequate'}; recent probes have not disrupted services.</small></div></div><div class="news-item"><div class="news-icon">◈</div><div class="news-copy"><strong>Domestic stability indicators</strong><small>Public approval ${Math.round(state.approval)}% · coalition cohesion ${Math.round(state.coalition)}%.</small></div></div><div class="news-item"><div class="news-icon">◎</div><div class="news-copy"><strong>Foreign influence watch</strong><small>Trade disputes and misinformation risk rise when bilateral relations deteriorate.</small></div></div></div></div><div class="card">${cardHead('National security council','Choose a lawful, accountable operation')}<div class="panel-body"><div class="control-row"><div class="control-top"><label>Security investment</label><output id="out-intel">${Math.round(state.intel)} index</output></div><input type="range" min="30" max="90" value="${state.intel}" oninput="state.intel=+this.value;document.getElementById('out-intel').textContent=this.value+' index'"><div class="hint">Infrastructure and cyber defence investment improves warning capacity.</div></div><button class="btn" onclick="intelAction('audit')">Independent oversight audit</button><button class="btn" style="margin-left:7px" onclick="intelAction('resilience')">Public resilience campaign</button><div class="notice" style="margin-top:14px">Intelligence is a decision-support tool, not a substitute for evidence. Operations are subject to parliamentary and judicial oversight.</div></div></div></div><div class="card" style="margin-top:14px">${cardHead('Security timeline','Recent assessments and incident reports')}<div class="panel-body">${state.news.filter(n=>['Security','Intelligence','Diplomacy'].includes(n.type)).slice(0,5).map(n=>`<div class="news-item"><div class="news-icon">⌖</div><div class="news-copy"><strong>${n.title}</strong><small>${n.date} · ${n.detail}</small></div></div>`).join('')||'<div class="muted" style="font-size:10px">No active incident reports. The intelligence director will alert you if conditions change.</div>'}</div></div>`}
function newsPage(){return `${header('News & presidential decisions','Minister briefings, national events, and the record of your administration.',`<button class="btn" onclick="save()">Save game</button>`)}<div class="grid two-col"><div class="card">${cardHead('News desk','Official briefings and world dispatches')}<div class="panel-body">${state.news.length?state.news.map(n=>`<div class="news-item"><div class="news-icon">${n.type==='Security'?'⌖':n.type==='Diplomacy'?'◎':n.type==='Economy'?'↗':'▤'}</div><div class="news-copy"><span class="tag" style="margin-bottom:5px">${n.type} · ${n.date}</span><strong>${n.title}</strong><small>${n.detail}</small></div></div>`).join(''):'<div class="notice">No dispatches yet. Advance time to receive your first cabinet briefing.</div>'}</div></div><div><div class="card event-card"><div class="event-kicker"><span>◉ Presidential decision</span><span class="tag gold">${state.activeEvent?state.activeEvent.type:'Awaiting report'}</span></div><h3>${state.activeEvent?state.activeEvent.title:'No decision pending'}</h3><p>${state.activeEvent?state.activeEvent.text:'Advance the calendar to trigger dynamic events and cabinet briefings.'}</p><button class="btn gold" onclick="${state.activeEvent?'openEvent()':'advance()'}">${state.activeEvent?'Review & decide':'Advance month'} →</button></div><div class="card" style="margin-top:14px">${cardHead('Administration record','A living political legacy')}<div class="panel-body"><div class="bar-row"><span class="bar-label">Months served</span><div class="bar-track"><div class="bar-fill" style="width:${state.month/48*100}%"></div></div><span class="bar-value">${state.month}/48</span></div><div class="bar-row"><span class="bar-label">Approval</span><div class="bar-track"><div class="bar-fill" style="width:${state.approval}%"></div></div><span class="bar-value">${Math.round(state.approval)}</span></div><div class="pill-row"><span class="tag">GDP ₡${state.gdp.toFixed(0)}B</span><span class="tag">Debt ₡${state.debt.toFixed(0)}B</span><span class="tag">Projects ${state.projects.length}</span></div><button class="btn small" style="margin-top:13px" onclick="save()">Save presidential archive</button></div></div></div></div>`}
function render(){const content=({overview:dashboard,economy,government,military,diplomacy,infrastructure,intelligence,news:newsPage}[page]||dashboard)();app.innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">M</div><div><div class="brand-name">MANDATE</div><div class="brand-sub">PRESIDENT SIMULATOR</div></div></div><div class="nav-label">EXECUTIVE OFFICE</div><nav class="nav">${navItems.map(([id,icon,label])=>`<button class="${page===id?'active':''}" onclick="navigate('${id}')"><span class="ico">${icon}</span><span class="label">${label}</span></button>`).join('')}</nav><div class="side-spacer"></div><div class="side-country"><div class="country-row"><span class="flag">🇻🇪</span><strong>REPUBLIC OF VELORIA</strong></div><small>Population 18.4M · Capital Aster</small></div><div class="side-footer"><span><i class="status-dot"></i>Systems nominal</span><span>v1.0</span></div></aside><main class="main"><header class="topbar"><div class="crumb">VELORIA <span style="color:#53657a"> / </span> <b>${navItems.find(n=>n[0]===page)?.[2]||'Overview'}</b></div><div class="top-actions"><div class="date-chip"><span>▦</span><b>${monthName(state.month)} ${state.year}</b></div><div class="speed-control"><button class="${state.speed===0?'selected':''}" onclick="setSpeed(0)">Ⅱ</button><button class="${state.speed===1?'selected':''}" onclick="setSpeed(1)">1×</button><button class="${state.speed===2?'selected':''}" onclick="setSpeed(2)">2×</button></div><button class="icon-btn" aria-label="Save game" title="Save game" onclick="save()">⌑</button><button class="icon-btn" aria-label="Notifications" title="Notifications" onclick="navigate('news')">♧<i class="notif-dot"></i></button><div class="avatar">MV</div></div></header><section class="content">${content}</section></main></div>${activeModal?modalMarkup():''}`;}
function navigate(id){page=id;render()}
function modalMarkup(){if(activeModal.kind==='event'){const e=state.activeEvent;if(!e)return '';return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><div class="modal-kicker">${e.type} · MINISTER BRIEFING</div><h2>${e.title}</h2></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body"><p>${e.text}</p><strong style="color:#d7e0e9">Choose the presidential response:</strong>${e.choices.map((c,i)=>`<button class="choice" onclick="resolveEvent(${i})"><strong>${c[0]}</strong><span>${c[1]}<br><span style="color:#e4c87f">${c[2]}</span></span></button>`).join('')}</div><div class="modal-footer"><span>Consequences may unfold over time.</span><span>${monthName(state.month)} ${state.year}</span></div></div></div>`}if(activeModal.kind==='simple'){return `<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal"><div class="modal-head"><div><div class="modal-kicker">${activeModal.kicker||'PRESIDENTIAL OFFICE'}</div><h2>${activeModal.title}</h2></div><button class="modal-close" onclick="closeModal()">×</button></div><div class="modal-body">${activeModal.body||''}</div><div class="modal-footer"><span>${activeModal.footer||'Actions have lasting consequences.'}</span><button class="btn small" onclick="closeModal()">Close</button></div></div></div>`}return ''}
function closeModal(){activeModal=null;render()}
function setBudget(key,val){state.budget[key]=+val;const out=document.getElementById('out-'+key);if(out)out.textContent=`${val}%`;renderBudgetNotice()}
function renderBudgetNotice(){const note=document.querySelector('.notice');if(note&&page==='economy'){const total=Object.values(state.budget).reduce((a,b)=>a+b,0);note.innerHTML=`<strong>Allocation: ${total}% of GDP.</strong> Tax revenue is ${state.tax}%. ${total>state.tax?'This budget adds to public debt.':'Surplus supports treasury reserves and debt reduction.'}`}}
function setTax(v){state.tax=+v;const o=document.getElementById('out-tax');if(o)o.textContent=`${v}%`;renderBudgetNotice()}
function setPolicy(v){state.policy=v;toast(`Fiscal doctrine set: ${v}`)}
function setDiplomacy(v){state.diplomacy=v;toast(`Foreign affairs approach: ${v}`)}
function setPosture(v){state.posture=v;toast(`Defence posture: ${v}`)}
function setSpeed(v){state.speed=v;updateTimer();render()}
function updateTimer(){clearInterval(tickTimer);if(state.speed){tickTimer=setInterval(()=>{if(!activeModal&&!state.gameOver)advance(true)},state.speed===1?15000:7000)}}
function advance(automatic=false){if(state.activeEvent&&!automatic){openEvent();return}if(state.gameOver)return;if(!automatic&&state.activeEvent)state.activeEvent=null;const total=Object.values(state.budget).reduce((a,b)=>a+b,0),rev=state.gdp*state.tax/1200,spend=state.gdp*total/1200,delta=rev-spend;state.treasury+=delta;state.debt-=delta;if(state.treasury<0){state.debt+=Math.abs(Math.min(0,state.treasury))*.12}const infraBonus=(state.infrastructure-50)*.004,educationBonus=(state.education-50)*.003,tradeBonus=state.countries.reduce((a,c)=>a+c.trade,0)*.0004;let policyBonus=state.policy==='Public investment'?.12:state.policy==='Industrial renewal'?.1:state.policy==='Austerity'?-.08:0;state.growth=clamp(state.growth+infraBonus+educationBonus+tradeBonus+policyBonus-(state.inflation>6?.12:0),-1.5,1.8);state.gdp*=1+state.growth/100;state.inflation=clamp(state.inflation+(state.tax>30?.08:0)-(state.budget.health+state.budget.welfare>9?.04:0)+(state.growth>.8?.06:0),.2,15);state.unemployment=clamp(state.unemployment-(state.growth>.35?.12:-.05)+(state.inflation>7?.08:0),2,25);state.readiness=clamp(state.readiness+(state.budget.defence-5)*.035-.2);state.army=clamp(state.army+(state.budget.defence-5)*.018-.08);state.air=clamp(state.air+(state.budget.defence-5)*.015-.1);state.navy=clamp(state.navy+(state.budget.defence-5)*.014-.08);state.health=clamp(state.health+(state.budget.health-5)*.05-.08);state.education=clamp(state.education+(state.budget.education-4)*.045-.05);state.infrastructure=clamp(state.infrastructure+(state.budget.infrastructure-4)*.05-.06);state.stability=clamp(state.stability+(state.approval-50)*.025+(state.health-50)*.006-(state.inflation>8?.4:0));state.approval=clamp(state.approval+(state.growth>.4?.18:-.14)-(state.inflation>6?.25:0)-(state.unemployment>9?.18:0)+(state.health>60?.05:0));state.coalition=clamp(state.coalition+(state.approval>55?.06:-.12)-(state.corruption>50?.2:0));state.loyalty=clamp(state.loyalty+(state.budget.defence>=15?.08:-.15)+(state.stability<40?-.2:0));state.threat=clamp(state.threat+(state.stability<40?.5:-.08)+(state.countries.filter(c=>c.relation<25).length*.1));state.corruption=clamp(state.corruption-(state.policy==='Austerity'?.02:0));for(const c of state.countries){const drift=(state.diplomacy==='Trade-first diplomacy'?.12:0)+(state.diplomacy==='Constructive engagement'?.06:0)+(state.tradeDeals?.[c.id]?.05:0);c.relation=clamp(c.relation+drift+(c.relation<24?-.12:0));if(c.relation>55)c.trade=Math.min(60,c.trade+.08);else if(c.relation<25)c.trade=Math.max(0,c.trade-.15);c.gdp*=1+(c.relation>55?.003:c.relation<25?-.002:.001)}state.projects=state.projects.map(p=>({...p,remaining:p.remaining-1,progress:Math.min(100,p.progress+100/p.duration)}));const finished=state.projects.filter(p=>p.remaining<=0);finished.forEach(p=>{completeProject(p);addNews(`${p.name} opens for service`,`The ${p.name.toLowerCase()} project is complete and enters operation.`,'Infrastructure')});state.projects=state.projects.filter(p=>p.remaining>0);state.month++;if(state.month>12){state.month=1;state.year++}state.chart.push(state.gdp);state.chart=state.chart.slice(-12);state.history.unshift({month:state.month,year:state.year,gdp:state.gdp,approval:state.approval});state.history=state.history.slice(0,60);if(state.month===1&&state.year%4===0)holdElection();autonomousWorld();const ev=eventPool[Math.floor(Math.random()*eventPool.length)];if(Math.random()<.86){state.activeEvent=JSON.parse(JSON.stringify(ev));state.activeEvent.choices=ev.choices;addNews(ev.title,ev.text,ev.type)}else{state.activeEvent=null;addNews('A measured month for Veloria','Your ministers report steady operations across the government.','Briefing')}checkGameOver();if(!automatic)toast(`Calendar advanced · ${monthName(state.month)} ${state.year}`);render();if(state.activeEvent&&!automatic)setTimeout(()=>{if(state.activeEvent&&!activeModal)openEvent()},260)}
function autonomousWorld(){for(const c of state.countries){const random=(Math.random()-.5);c.gdp*=1+random*.004;c.army=clamp(c.army+(Math.random()-.52)*.4);if(Math.random()<.06){const shift=Math.random()<.5?1:-1;c.relation=clamp(c.relation+shift*2);if(c.relation<20)c.stance='Tense';if(c.relation>65)c.stance='Partner'}}}
function openEvent(){if(!state.activeEvent)return;activeModal={kind:'event'};render()}
function resolveEvent(i){const e=state.activeEvent;if(!e)return;const choice=e.choices[i];choice[3](state);state.approval=clamp(state.approval);state.coalition=clamp(state.coalition);state.stability=clamp(state.stability);state.treasury=clamp(state.treasury,-20,500);addNews(`Decision: ${choice[0]}`,choice[1],e.type);state.history.unshift({month:state.month,year:state.year,decision:choice[0]});state.activeEvent=null;activeModal=null;checkGameOver();saveQuiet();render();toast(`Decision recorded: ${choice[0]}`)}
function simpleModal(title,body,kicker='PRESIDENTIAL OFFICE',footer='Actions have lasting consequences.'){activeModal={kind:'simple',title,body,kicker,footer};render()}
function openPolicyModal(){simpleModal('Set a national policy',`<p>Choose a governing priority. The effects are gradual and will shape economic performance and public confidence.</p><div class="choice-list"><button class="choice" onclick="choosePolicy('Balanced growth')"><strong>Balanced growth</strong><span>Maintain the current mix of investment and fiscal restraint.</span></button><button class="choice" onclick="choosePolicy('Public investment')"><strong>Public investment</strong><span>Boost growth and services; coalition support may soften.</span></button><button class="choice" onclick="choosePolicy('Industrial renewal')"><strong>Industrial renewal</strong><span>Prioritize productivity and domestic manufacturing.</span></button><button class="choice" onclick="choosePolicy('Austerity')"><strong>Fiscal restraint</strong><span>Reduce corruption and spending pressure, at the cost of growth.</span></button></div>`,'LEGISLATIVE AGENDA')}
function choosePolicy(policy){state.policy=policy;if(policy==='Public investment'){state.approval=clamp(state.approval+1);state.coalition=clamp(state.coalition-1)}else if(policy==='Austerity'){state.approval=clamp(state.approval-1);state.corruption=clamp(state.corruption-1)}else if(policy==='Industrial renewal'){state.growth=clamp(state.growth+.08,-1.5,1.8)}addNews('National policy adopted',`The administration has set its governing doctrine to ${policy}.`,'Politics');closeModal();saveQuiet();toast(`Policy adopted: ${policy}`)}
function replaceMinister(i){const minister=state.ministers[i];if(!minister)return;const candidates=[['Nadia Pell','Experienced civil servant'],['Arin Sorell','Independent policy specialist'],['Marek Dovan','Coalition representative']];simpleModal(`Replace ${minister.role} minister`,`<p>Replacing ${minister.name} will create a short period of disruption but may refresh public confidence.</p>${candidates.map(([name,bio],n)=>`<button class="choice" onclick="appointMinister(${i},${n})"><strong>${name}</strong><span>${bio} · Cabinet confidence ${n===0?'High':n===1?'Moderate':'Coalition-backed'}</span></button>`).join('')}`,'CABINET APPOINTMENT')}
function appointMinister(i,n){const candidates=[['Nadia Pell','Experienced civil servant'],['Arin Sorell','Independent policy specialist'],['Marek Dovan','Coalition representative']];const c=candidates[n],m=state.ministers[i];if(!c||!m)return;m.name=c[0];m.bio=c[1];state.approval=clamp(state.approval+1);state.coalition=clamp(state.coalition-(n===2?0:1));state.stability=clamp(state.stability-.3);addNews(`${m.role} minister replaced`,`${c[0]} has been sworn in as ${m.role} minister.`,'Politics');closeModal();saveQuiet();toast(`${m.role} portfolio updated`)}
function coalitionAction(action){if(action==='consult'){state.coalition=clamp(state.coalition+3);state.approval=clamp(state.approval+1);state.treasury=clamp(state.treasury-.3,-20,500);addNews('Coalition council convened','Partners agreed to a shared legislative calendar after consultations.','Politics');toast('Coalition support improved')}else if(action==='reform'){state.corruption=clamp(state.corruption-5);state.stability=clamp(state.stability+2);state.coalition=clamp(state.coalition-1);addNews('Integrity charter introduced','An independent procurement and ethics office will publish quarterly audits.','Politics');toast('Integrity charter adopted')}saveQuiet();render()}
function openProcurement(){simpleModal('Defence procurement & recruitment',`<p>Choose a limited, defensive investment. Costs are paid from the treasury immediately; projects complete over several months.</p><div class="choice" onclick="startProject('military','Secure communications',3,3)"><strong>Secure communications · ₡3B</strong><span>Improve command resilience and intelligence capacity.</span></div><div class="choice" onclick="startProject('military','Air-defence modernization',5,5)"><strong>Air-defence modernization · ₡5B</strong><span>Raise readiness and strengthen protection of national airspace.</span></div><div class="choice" onclick="startProject('military','Fleet renewal',4,4)"><strong>Fleet renewal · ₡4B</strong><span>Improve maritime patrol capacity and coastal resilience.</span></div><div class="choice" onclick="recruitPersonnel()"><strong>Recruit 5,000 personnel · ₡2B</strong><span>Expand staffing; recurring payroll modestly increases defence costs.</span></div>`,'DEFENCE MINISTRY')}
function recruitPersonnel(){if(state.treasury<2){toast('Insufficient treasury reserves');return}state.treasury-=2;state.personnel+=5;state.readiness=clamp(state.readiness+1);state.loyalty=clamp(state.loyalty+1);addNews('Recruitment authorization signed','Five thousand personnel will join the armed forces over the coming year.','Security');closeModal();saveQuiet();render();toast('Recruitment approved')}
function militaryAction(action){if(action==='exercise'){if(state.treasury<1.2){toast('Insufficient treasury reserves');return}state.treasury-=1.2;state.readiness=clamp(state.readiness+5);state.army=clamp(state.army+1);state.air=clamp(state.air+.6);state.stability=clamp(state.stability+.4);addNews('Joint readiness exercise completed','A limited, defensive exercise improved inter-service coordination.','Security');toast('Readiness improved')}else{state.loyalty=clamp(state.loyalty+5);state.corruption=clamp(state.corruption-2);state.stability=clamp(state.stability+1);addNews('Civilian oversight strengthened','Parliamentary reporting and independent procurement review expanded.','Politics');toast('Oversight safeguards strengthened')}saveQuiet();render()}
function diplomaticAction(action){if(action==='summit'){if(state.treasury<1){toast('Insufficient treasury reserves');return}state.treasury-=1;state.countries.forEach(c=>{if(c.id!=='veloria')c.relation=clamp(c.relation+(c.relation<35?3:1))});state.stability=clamp(state.stability+1);state.threat=clamp(state.threat-2);addNews('Regional summit convened','Veloria hosted talks on trade, maritime safety, and crisis communications.','Diplomacy');saveQuiet();render();toast('Regional ties strengthened')}}
function countryAction(id,action){const c=state.countries.find(x=>x.id===id);if(!c)return;if(action==='trade'){if(state.treasury<1){toast('Insufficient treasury reserves');return}state.treasury-=1;c.relation=clamp(c.relation+4);c.trade=Math.min(60,c.trade+4);state.growth=clamp(state.growth+.05,-1.5,1.8);addNews(`Trade framework with ${c.name}`,`A commercial delegation opened negotiations on market access and investment safeguards.`,'Diplomacy');toast(`Trade talks opened with ${c.name}`)}else if(action==='treaty'){if(c.relation<35){simpleModal('Treaty proposal not ready',`<p>Relations with ${c.name} are too strained for a durable agreement. Consider a summit or trade dialogue first.</p>`,'FOREIGN OFFICE');return}if(state.treasury<.5){toast('Insufficient treasury reserves');return}state.treasury-=.5;c.relation=clamp(c.relation+7);c.trade=Math.min(60,c.trade+2);state.flags=state.flags||{};state.flags[`treaty-${id}`]=true;addNews(`${c.name} treaty signed`,`A bilateral cooperation framework was concluded with ${c.name}.`,'Diplomacy');toast('Treaty concluded')}else{if(state.treasury<.3){toast('Insufficient treasury reserves');return}state.treasury-=.3;c.relation=clamp(c.relation-12);c.trade=Math.max(0,c.trade-3);state.threat=clamp(state.threat+2);state.stability=clamp(state.stability-1);addNews(`Targeted sanctions on ${c.name}`,`The government announced limited measures with a review clause and humanitarian exemptions.`,'Diplomacy');toast(`Measures imposed on ${c.name}`)}saveQuiet();render()}
function openBuildModal(){simpleModal('Commission a national project',`<p>Select a project to fund. The full cost is deducted now; benefits arrive when construction is complete.</p><div class="choice" onclick="buildProject('roads','Highway renewal',4,4)"><strong>Highway renewal · ₡4B · 4 months</strong><span>Connect rural producers to the central freight corridor.</span></div><div class="choice" onclick="buildProject('power','Grid modernization',5,5)"><strong>Grid modernization · ₡5B · 5 months</strong><span>Reduce outages and improve industrial capacity.</span></div><div class="choice" onclick="buildProject('hospital','Regional hospitals',4,4)"><strong>Regional hospitals · ₡4B · 4 months</strong><span>Expand emergency and maternity care.</span></div><div class="choice" onclick="buildProject('school','Technical schools',3,5)"><strong>Technical schools · ₡3B · 5 months</strong><span>Train workers for manufacturing and clean technology.</span></div><div class="choice" onclick="buildProject('port','Deep-water port',6,6)"><strong>Deep-water port · ₡6B · 6 months</strong><span>Increase export capacity and maritime access.</span></div><div class="choice" onclick="buildProject('factory','Industrial innovation park',5,5)"><strong>Industrial innovation park · ₡5B · 5 months</strong><span>Attract advanced manufacturing and skilled jobs.</span></div>`,'PUBLIC WORKS')}
function buildProject(kind,name,cost,duration){startProject(kind,name,cost,duration)}
function startProject(kind,name,cost,duration){cost=Number(cost);duration=Number(duration);if(state.treasury<cost){toast('Insufficient treasury reserves');return}if(state.projects.some(p=>p.name===name)){toast('That project is already underway');return}state.treasury-=cost;state.projects.push({id:`project-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,kind,name,cost,duration,remaining:duration,progress:0});addNews(`${name} commissioned`,`The ${name.toLowerCase()} project is funded at ₡${cost}B and is expected to take ${duration} months.`,'Infrastructure');activeModal=null;saveQuiet();render();toast(`${name} commissioned`)}
function projectCard(p){return `<div class="project"><div class="project-line"><span class="project-name">${p.name}</span><span class="tag">${Math.round(p.progress||0)}% · ${Math.max(0,p.remaining)} mo left</span></div><div class="progress" style="height:6px;margin:9px 0"><span style="width:${clamp(p.progress||0)}%"></span></div><div class="project-desc">Initial investment ₡${Number(p.cost||0).toFixed(1)}B · ${p.kind==='military'?'Defence':'Public works'}</div></div>`}
function completeProject(p){switch(p.kind){case 'roads':state.infrastructure=clamp(state.infrastructure+3);state.growth=clamp(state.growth+.12,-1.5,1.8);break;case 'power':state.infrastructure=clamp(state.infrastructure+3);state.growth=clamp(state.growth+.18,-1.5,1.8);state.inflation=clamp(state.inflation-.2);break;case 'hospital':state.health=clamp(state.health+5);state.approval=clamp(state.approval+2);break;case 'school':state.education=clamp(state.education+5);state.unemployment=clamp(state.unemployment-.3);break;case 'port':state.infrastructure=clamp(state.infrastructure+4);state.countries.forEach(c=>c.trade=Math.min(60,c.trade+.5));break;case 'factory':state.growth=clamp(state.growth+.2,-1.5,1.8);state.unemployment=clamp(state.unemployment-.5);state.approval=clamp(state.approval+1);break;case 'military':state.readiness=clamp(state.readiness+(p.name.includes('Air')?7:4));state.air=clamp(state.air+(p.name.includes('Air')?5:1));state.navy=clamp(state.navy+(p.name.includes('Fleet')?5:0));state.intel=clamp(state.intel+(p.name.includes('communications')?4:0));break}saveQuiet()}
function intelAction(action){if(action==='review'){state.intel=clamp(state.intel+2);state.threat=clamp(state.threat-1);addNews('Intelligence review completed','The security council reviewed threat indicators, collection priorities, and legal safeguards.','Intelligence');toast('Assessment updated')}else if(action==='audit'){state.corruption=clamp(state.corruption-4);state.intel=clamp(state.intel-1);state.stability=clamp(state.stability+2);addNews('Independent oversight audit','An external inspector reviewed agency authorities and expenditure.','Intelligence');toast('Oversight audit completed')}else{if(action==='resilience'){state.stability=clamp(state.stability+3);state.threat=clamp(state.threat-2);state.approval=clamp(state.approval+1);addNews('Public resilience campaign','Civil preparedness and trusted information resources were expanded.','Intelligence');toast('Resilience improved')}}saveQuiet();render()}
function saveQuiet(){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){}}
function checkGameOver(){if(state.treasury<-8){state.gameOver='Treasury default';state.speed=0;updateTimer()}else if(state.stability<12){state.gameOver='National crisis';state.speed=0;updateTimer()}else if(state.loyalty<12&&state.stability<28){state.gameOver='Civil-military crisis';state.speed=0;updateTimer()}else if(state.approval<8&&state.coalition<15){state.gameOver='Government loses confidence';state.speed=0;updateTimer()}if(state.gameOver){activeModal={kind:'simple',kicker:'END OF ADMINISTRATION',title:state.gameOver,body:`<p>Your administration has reached a constitutional breaking point in ${monthName(state.month)} ${state.year}.</p><div class="notice">You served ${((state.year-2028)*12+state.month)} months. GDP: ₡${state.gdp.toFixed(0)}B · Public approval: ${Math.round(state.approval)}%.</div><button class="btn gold" style="margin-top:12px" onclick="newGame()">Begin a new administration</button>`,footer:'Your political legacy is recorded.'}}}
function holdElection(){const result=state.approval+state.coalition*.18+(Math.random()*12-6);if(result<48){state.coalition=clamp(state.coalition-18);state.approval=clamp(state.approval-5);addNews('Election produces a divided parliament','The governing coalition loses seats. You retain office but must negotiate a new legislative agenda.','Politics')}else{state.coalition=clamp(state.coalition+7);state.approval=clamp(state.approval+3);addNews('Governing coalition renewed','Voters return your government with a working mandate.','Politics')}}
function newGame(){state=freshState();page='overview';activeModal=null;localStorage.removeItem(SAVE_KEY);render();toast('A new administration begins')}

render();
